One table files whole words and another counts visits, and both are built in the same loop. Which pair names what this program prints and why?

bins = {}
groups = {}
for w in ["ant", "ape", "bat"]:
    bins.setdefault(w[0], []).append(w)
    groups.setdefault(w[0], 0)
    groups[w[0]] += 1
print(bins["a"], groups["b"], len(bins), sum(groups.values()))

A halving search is run on a properly ordered list twice and then on a list whose order was broken. What does this program print?

def find(items, target):
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
data = [1, 3, 3, 5, 7, 7, 9]
print(find(data, 7), find(data, 3), find([4, 1, 3, 2], 2))

A pair search remembers where it has already looked, and it is run on a list that has a pair and on one that does not. What does this program print?

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return seen[target - x], i
        seen[x] = i
    return None
print(two_sum([2, 7, 11, 15], 9), two_sum([1, 2], 5))

A window over a list of words is grown one end at a time and its start is advanced while the words repeat, then the same routine is run on an empty list. What does this program print?

def longest(words):
    best = 0
    start = 0
    for end in range(len(words)):
        while len(set(words[start:end + 1])) != end + 1 - start:
            start += 1
        best = max(best, end + 1 - start)
    return best
print(longest(["aa", "bb", "aa", "cc"]), longest([]))

The same graph is walked twice, once by a recursive routine that goes as deep as it can and once by a routine that grows a list of the frontier. Which pair names what this program prints and why?

graph = {"a": ["b", "c"], "b": ["d"], "c": ["d"], "d": []}
depth_first = []
def dfs(node):
    depth_first.append(node)
    for nxt in graph[node]:
        if nxt not in depth_first:
            dfs(nxt)
dfs("a")
width_first = ["a"]
for node in width_first:
    for nxt in graph[node]:
        if nxt not in width_first:
            width_first.append(nxt)
print(depth_first, width_first)

