A walk starts from one node, takes nodes off a queue, and records a neighbour as soon as it is queued. What does this program print?

from collections import deque
graph = {"a": ["b", "c"], "b": ["d"], "c": [], "d": []}
q = deque(["a"])
order = []
seen = {"a"}
while q:
    node = q.popleft()
    order.append(node)
    for nxt in graph[node]:
        if nxt not in seen:
            seen.add(nxt)
            q.append(nxt)
print(order, len(seen))

