A recursive routine records every index it is asked about, including the ones it answers from its table rather than by recursing. What does this program print?

calls = []
def fib(n, memo=None):
    if memo is None:
        memo = {}
    calls.append(n)
    if n < 2:
        return n
    if n in memo:
        return memo[n]
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]
print(fib(12), len(calls))

A routine claims to be linear because its membership test is a single pass, and the loop around it is instrumented to count its iterations. What does this program print?

data = list(range(10))
def has_dup(xs):
    return len(set(xs)) != len(xs)
n = 0
for i in range(len(data)):
    for j in range(len(data)):
        n += 1
print(has_dup(data), n)
